<section class="page-heading"><div><h1>Sales history</h1><p><?= (int)$listing['total'] ?> invoices</p></div><?php if(can($user,'pos.access') && can($user,'sales.create')): ?><a class="button button-primary" href="<?= e(url('/pos')) ?>">New sale</a><?php endif; ?></section>
<?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif; ?>
<form class="surface product-filters sales-filters" method="get"><input type="hidden" name="route" value="/sales"><label>Search invoice / customer<input name="q" type="search" value="<?= e($filters['q']??'') ?>"></label><?php foreach(['from'=>'From','to'=>'To'] as $k=>$label): ?><label><?= e($label) ?><input name="<?= e($k) ?>" type="date" value="<?= e($filters[$k]??'') ?>"></label><?php endforeach; ?><label>Payment<select name="payment"><option value="">All</option><?php foreach(['paid','partial','unpaid','reversed'] as $v): ?><option <?= ($filters['payment']??'')===$v?'selected':'' ?> value="<?= e($v) ?>"><?= e(ucfirst($v)) ?></option><?php endforeach; ?></select></label><label>Sale status<select name="status"><option value="">All</option><?php foreach(['posted','cancelled'] as $v): ?><option value="<?= e($v) ?>" <?= ($filters['status']??'')===$v?'selected':'' ?>><?= e(ucfirst($v)) ?></option><?php endforeach; ?></select></label><label>Sort<select name="sort"><?php foreach(['date'=>'Date','number'=>'Invoice number','total'=>'Total','due'=>'Outstanding'] as $v=>$label): ?><option value="<?= e($v) ?>" <?= ($filters['sort']??'date')===$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Direction<select name="direction"><option value="desc">Descending</option><option value="asc" <?= ($filters['direction']??'')==='asc'?'selected':'' ?>>Ascending</option></select></label><div class="product-actions"><button class="button button-primary">Apply</button><a class="button" href="<?= e(url('/sales')) ?>">Clear</a></div></form>
<div class="surface table-scroll"><table class="sales-table"><thead><tr><th>Invoice / Date</th><th>Customer</th><th>Items</th><th>Total</th><th>Paid</th><th>Outstanding</th><th>Payment / Status</th><th>Actions</th></tr></thead><tbody><?php foreach($listing['rows'] as $s): $customer=json_decode($s['customer_snapshot'],true); ?><tr><td data-label="Invoice"><strong><?= e($s['invoice_number']) ?></strong><small><?= e(local_datetime($s['created_at'])) ?></small></td><td data-label="Customer"><?= e($customer['name']) ?><small><?= e($customer['phone']??'') ?></small></td><td data-label="Items"><?= (int)$s['item_count'] ?></td><td data-label="Total"><?= money($s['total']) ?></td><td data-label="Paid"><?= money($s['amount_paid']) ?></td><td data-label="Outstanding"><?= $s['cancellation_id']?'₹0.00 (cancelled)':money($s['balance_due']) ?></td><td data-label="Status"><?= $s['cancellation_id']?'Reversed':(bccomp($s['balance_due'],'0',2)===0?'Paid':(bccomp($s['amount_paid'],'0',2)>0?'Partial':'Unpaid')) ?> · <?= $s['cancellation_id']?'Cancelled':'Posted' ?></td><td data-label="Actions"><a class="button button-small" href="<?= e(url('/sales/invoice')) ?>&amp;id=<?= (int)$s['id'] ?>">View</a><?php if(can($user,'sales.reprint')): ?> <a class="text-link" href="<?= e(url('/sales/print')) ?>&amp;id=<?= (int)$s['id'] ?>">Print</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$listing['rows']): ?><p class="empty-state">No invoices match these filters.</p><?php endif; ?></div>
<nav class="pagination" aria-label="Sales pages"><?php foreach(['Previous'=>$listing['page']-1,'Next'=>$listing['page']+1] as $label=>$page): if($page<1 || $page>$listing['pages'])continue; ?><a class="button button-small" href="<?= e(url('/sales').'&'.http_build_query(array_merge(array_diff_key($filters,['route'=>true]),['page'=>$page]))) ?>"><?= e($label) ?></a><?php endforeach; ?><span>Page <?= (int)$listing['page'] ?> of <?= (int)$listing['pages'] ?></span></nav>
